//! Durable live node payloads with a bounded clean-record cache. The reference
//! kernel keeps mutation/scheduler metadata separately; it does not keep FP
//! centroids when this mode is active. This is local provider-backed storage.
use super::{topology_access::*,writer::persistence::block_on_for_sync_writer};
use anyhow::{ensure,Result};
use chroma_blockstore::{provider::BlockfileProvider,arrow::provider::BlockfileReaderOptions,BlockfileWriterOptions};
use parking_lot::{Mutex,RwLock,RwLockReadGuard,RwLockWriteGuard};
use std::{cell::RefCell,collections::{BTreeMap,VecDeque},sync::{Arc,atomic::{AtomicBool,AtomicU64,Ordering}}};
use uuid::Uuid;
use std::time::Instant;
struct Elapsed<'a>(&'a AtomicU64,Instant);
impl Drop for Elapsed<'_>{fn drop(&mut self){self.0.fetch_add(self.1.elapsed().as_nanos().min(u64::MAX as u128) as u64,Ordering::Relaxed);}}
thread_local!{static WRITES:RefCell<BTreeMap<usize,usize>>=RefCell::new(BTreeMap::new());}
#[derive(Clone,Copy)]pub struct Limits{pub entries:usize,pub cache_payload_bytes:usize,pub record_payload_bytes:usize,pub wave_rows:usize,pub mutation_working_bytes:usize}
impl Default for Limits{fn default()->Self{Self{entries:16,cache_payload_bytes:64*1024,record_payload_bytes:64*1024,wave_rows:16,mutation_working_bytes:4*1024*1024}}}
#[derive(Default)]struct Cache{records:BTreeMap<(usize,Uuid,u32),Arc<NodeRecord>>,order:VecDeque<(usize,Uuid,u32)>,bytes:usize,peak:usize,peak_entries:usize,evictions:u64,hits:u64,misses:u64}
pub struct LiveTopology{provider:BlockfileProvider,roots:Vec<Mutex<Option<Uuid>>>,cache:Mutex<Cache>,pending:Mutex<BTreeMap<(usize,u32),Option<NodeRecord>>>,pub limits:Limits,dim:usize,gate:RwLock<()>,failed:AtomicBool,reads:AtomicU64,writes:AtomicU64,encoded_set_bytes:AtomicU64,returned_bytes:AtomicU64,working:AtomicU64,deferred_working:AtomicU64,working_peak:AtomicU64,epoch:AtomicU64,navigation:Mutex<NavigationWork>,fetch_elapsed_ns:AtomicU64,flush_elapsed_ns:AtomicU64,write_gate_wait_ns:AtomicU64,read_gate_wait_ns:AtomicU64}
pub struct WriteScope<'a>{store:&'a LiveTopology,_guard:Option<RwLockWriteGuard<'a,()>>}
impl Drop for WriteScope<'_>{fn drop(&mut self){let key=self.store as *const _ as usize;WRITES.with(|v|{let mut v=v.borrow_mut();let depth=v.get_mut(&key).unwrap();*depth-=1;if *depth==0{v.remove(&key);self.store.epoch.fetch_add(1,Ordering::Release);}});}}
pub struct ReadScope<'a>{_guard:Option<RwLockReadGuard<'a,()>>}
pub struct Working<'a>{store:&'a LiveTopology,bytes:u64}
impl Drop for Working<'_>{fn drop(&mut self){if self.store.owns_write(){self.store.deferred_working.fetch_add(self.bytes,Ordering::Relaxed);}else{self.store.working.fetch_sub(self.bytes,Ordering::Relaxed);}}}
impl LiveTopology{
 pub fn new(provider:BlockfileProvider,owners:usize,dim:usize,limits:Limits)->Result<Self>{ensure!(owners>0 && owners<=8 && dim>0 && dim<=768 && limits.entries>0 && limits.entries<=256 && limits.cache_payload_bytes>0 && limits.record_payload_bytes>0 && limits.record_payload_bytes<=limits.cache_payload_bytes && limits.wave_rows>0 && limits.wave_rows<=64 && limits.mutation_working_bytes>0,"live topology admission");Ok(Self{provider,roots:(0..owners).map(|_|Mutex::new(None)).collect(),cache:Mutex::default(),pending:Mutex::default(),limits,dim,gate:RwLock::new(()),failed:AtomicBool::new(false),reads:AtomicU64::new(0),writes:AtomicU64::new(0),encoded_set_bytes:AtomicU64::new(0),returned_bytes:AtomicU64::new(0),working:AtomicU64::new(0),deferred_working:AtomicU64::new(0),working_peak:AtomicU64::new(0),epoch:AtomicU64::new(0),navigation:Mutex::default(),fetch_elapsed_ns:AtomicU64::new(0),flush_elapsed_ns:AtomicU64::new(0),write_gate_wait_ns:AtomicU64::new(0),read_gate_wait_ns:AtomicU64::new(0)})}
 pub fn owns_write(&self)->bool{let key=self as *const _ as usize;WRITES.with(|v|v.borrow().contains_key(&key))}
 pub fn write_scope(&self)->WriteScope<'_>{assert!(!self.failed.load(Ordering::Acquire),"poisoned live topology");let nested=self.owns_write();let guard=(!nested).then(||{let _timer=Elapsed(&self.write_gate_wait_ns,Instant::now());self.gate.write()});assert!(!self.failed.load(Ordering::Acquire),"poisoned after queued structural writer");let key=self as *const _ as usize;WRITES.with(|v|*v.borrow_mut().entry(key).or_default()+=1);WriteScope{store:self,_guard:guard}}
 pub fn read_scope(&self)->Result<ReadScope<'_>>{let guard=if self.owns_write(){None}else{Some({let _timer=Elapsed(&self.read_gate_wait_ns,Instant::now());self.gate.read()})};ensure!(!self.failed.load(Ordering::Acquire),"poisoned live topology");Ok(ReadScope{_guard:guard})}
 pub fn poison(&self){self.failed.store(true,Ordering::Release);}
 pub fn reserve_mutation(&self,records:usize)->Result<Working<'_>>{let bytes=records.checked_mul(self.limits.record_payload_bytes.checked_mul(4).and_then(|v|v.checked_add(512)).ok_or_else(||anyhow::anyhow!("mutation model overflow"))?).and_then(|v|v.checked_add(65536)).ok_or_else(||anyhow::anyhow!("mutation model overflow"))? as u64;let mut old=self.working.load(Ordering::Relaxed);loop{let next=old.checked_add(bytes).filter(|v|*v<=self.limits.mutation_working_bytes as u64).ok_or_else(||anyhow::anyhow!("topology mutation working budget before detach"))?;match self.working.compare_exchange_weak(old,next,Ordering::Relaxed,Ordering::Relaxed){Ok(_)=>{self.working_peak.fetch_max(next,Ordering::Relaxed);return Ok(Working{store:self,bytes});},Err(v)=>old=v}}}
 pub fn put(&self,owner:usize,mut record:NodeRecord)->Result<()> {
  ensure!(self.owns_write() && !self.failed.load(Ordering::Acquire),"live node mutation requires structural write scope");ensure!(owner<self.roots.len() && record.centroid.len()==self.dim && record.centroid.iter().all(|v|v.is_finite()) && record.payload_bytes()<=self.limits.record_payload_bytes,"live node payload admission");let previous=self.get(owner,record.id)?;let prior=previous.as_ref().map_or(0,|v|match v.binding{Binding::Live{epoch,..}=>epoch,_=>0});let incoming=match record.binding{Binding::Live{epoch,..}=>epoch,_=>0};let epoch=prior.max(incoming).checked_add(1).ok_or_else(||anyhow::anyhow!("live node epoch exhausted"))?;record.binding=Binding::Live{owner,epoch};
  let mut pending=self.pending.lock();self.admit_pending(&pending,(owner,record.id),record.payload_bytes())?;pending.insert((owner,record.id),Some(record));Ok(())
 }
 fn admit_pending(&self,pending:&BTreeMap<(usize,u32),Option<NodeRecord>>,key:(usize,u32),payload:usize)->Result<()>{let model=pending.iter().filter(|(k,_)|**k!=key).try_fold(65536usize,|sum,(_,v)|sum.checked_add(v.as_ref().map_or(0,|v|v.payload_bytes())*4+512)).and_then(|v|v.checked_add(payload*4+512)).ok_or_else(||anyhow::anyhow!("pending node model overflow"))?;ensure!(model as u64<=self.working.load(Ordering::Relaxed),"pending node payload exceeds pre-admitted mutation reservation");Ok(())}
 pub fn delete(&self,owner:usize,id:u32)->Result<()>{ensure!(self.owns_write(),"live delete requires structural write scope");let mut pending=self.pending.lock();self.admit_pending(&pending,(owner,id),0)?;pending.insert((owner,id),None);Ok(())}
 /// One durable root is committed per changed owner at the outer structural
 /// boundary. Dirty payload remains authoritative until every flush succeeds.
 pub fn flush(&self)->Result<()>{let _elapsed=Elapsed(&self.flush_elapsed_ns,Instant::now());ensure!(self.owns_write(),"live flush requires structural write scope");let pending=self.pending.lock().clone();if pending.is_empty(){self.working.fetch_sub(self.deferred_working.swap(0,Ordering::Relaxed),Ordering::Relaxed);return Ok(());}let mut accepted=Vec::new();let mut encoded=0usize;
  for owner in 0..self.roots.len(){let rows:Vec<_>=pending.iter().filter(|((o,_),_)|*o==owner).collect();if rows.is_empty(){continue;}let parent=*self.roots[owner].lock();let next=block_on_for_sync_writer(async{let mut options=BlockfileWriterOptions::new(String::new()).ordered_mutations().max_block_size_bytes(16*1024);if let Some(root)=parent{options=options.fork(root);}let writer=self.provider.write::<u32,Vec<u32>>(options).await.map_err(|e|anyhow::anyhow!("{e}"))?;for((_,id),record) in rows{if let Some(record)=record{let words=encode(record)?;encoded+=words.len()*4;writer.set("node",*id,words).await.map_err(|e|anyhow::anyhow!("{e}"))?;}else{writer.delete::<_,Vec<u32>>("node",*id).await.map_err(|e|anyhow::anyhow!("{e}"))?;}}let flush=writer.commit::<u32,Vec<u32>>().await.map_err(|e|anyhow::anyhow!("{e}"))?;let next=flush.id();flush.flush::<u32,Vec<u32>>().await.map_err(|e|anyhow::anyhow!("{e}"))?;Ok::<_,anyhow::Error>(next)})?;accepted.push((owner,next));
  }
  for(owner,root) in &accepted{*self.roots[*owner].lock()=Some(*root);}self.pending.lock().clear();self.writes.fetch_add(accepted.len() as u64,Ordering::Relaxed);self.encoded_set_bytes.fetch_add(encoded as u64,Ordering::Relaxed);self.working.fetch_sub(self.deferred_working.swap(0,Ordering::Relaxed),Ordering::Relaxed);Ok(())
 }
 pub fn get(&self,owner:usize,id:u32)->Result<Option<Arc<NodeRecord>>>{ensure!(!self.failed.load(Ordering::Acquire),"poisoned live topology");if let Some(record)=self.pending.lock().get(&(owner,id)).cloned(){return Ok(record.map(Arc::new));}let root=*self.roots.get(owner).ok_or_else(||anyhow::anyhow!("node owner missing"))?.lock();let Some(root)=root else{return Ok(None);};let key=(owner,root,id);{let mut c=self.cache.lock();if let Some(record)=c.records.get(&key).cloned(){c.hits+=1;c.order.retain(|v|*v!=key);c.order.push_back(key);return Ok(Some(record));}c.misses+=1;}
  self.reads.fetch_add(1,Ordering::Relaxed);let record={let _elapsed=Elapsed(&self.fetch_elapsed_ns,Instant::now());block_on_for_sync_writer(async{let reader=self.provider.read::<u32,&[u32]>(BlockfileReaderOptions::new(root,String::new())).await.map_err(|e|anyhow::anyhow!("{e}"))?;let value=reader.get("node",id).await.map_err(|e|anyhow::anyhow!("{e}"))?;let record=value.map(|words|decode(id,owner,words,self.dim,self.limits.record_payload_bytes)).transpose()?;reader.clear_loaded_blocks();Ok::<_,anyhow::Error>(record)})}?;let Some(record)=record else{return Ok(None);};let record=Arc::new(record);let bytes=record.payload_bytes();self.returned_bytes.fetch_add(bytes as u64,Ordering::Relaxed);let mut c=self.cache.lock();if let Some(v)=c.records.get(&key){return Ok(Some(v.clone()));}while c.records.len()>=self.limits.entries || c.bytes+bytes>self.limits.cache_payload_bytes{let victim=c.order.pop_front().expect("record fits empty cache");c.bytes-=c.records.remove(&victim).unwrap().payload_bytes();c.evictions+=1;}c.bytes+=bytes;c.records.insert(key,record.clone());c.order.push_back(key);c.peak=c.peak.max(c.bytes);c.peak_entries=c.peak_entries.max(c.records.len());Ok(Some(record))
 }
 pub fn record_navigation(&self,work:&NavigationWork){let mut total=self.navigation.lock();total.fetch_waves+=work.fetch_waves;total.requested_records+=work.requested_records;total.returned_payload_bytes+=work.returned_payload_bytes;total.distance_evaluations+=work.distance_evaluations;total.expanded_internals+=work.expanded_internals;total.levels+=work.levels;total.peak_wave_payload_bytes=total.peak_wave_payload_bytes.max(work.peak_wave_payload_bytes);total.peak_accounted_record_pin_payload_bytes=total.peak_accounted_record_pin_payload_bytes.max(work.peak_accounted_record_pin_payload_bytes);total.peak_frontier_scores=total.peak_frontier_scores.max(work.peak_frontier_scores);}
 pub fn report(&self)->serde_json::Value{let c=self.cache.lock();let navigation=self.navigation.lock();serde_json::json!({"durable_fetch_elapsed_ns":self.fetch_elapsed_ns.load(Ordering::Relaxed),"structural_flush_elapsed_ns":self.flush_elapsed_ns.load(Ordering::Relaxed),"write_gate_wait_elapsed_ns":self.write_gate_wait_ns.load(Ordering::Relaxed),"read_gate_wait_elapsed_ns":self.read_gate_wait_ns.load(Ordering::Relaxed),"timer_scope":"Fetch/flush/gate timers are cumulative caller elapsed including storage/waits/errors; concurrent readers overlap and structural flush is nested in balance/move/setup. Never subtract summed timers from wall time or call them CPU.","navigation_fetch_waves":navigation.fetch_waves,"navigation_requested_records":navigation.requested_records,"navigation_returned_payload_bytes":navigation.returned_payload_bytes,"navigation_peak_wave_payload_bytes":navigation.peak_wave_payload_bytes,"navigation_peak_accounted_parent_child_pin_payload_bytes":navigation.peak_accounted_record_pin_payload_bytes,"navigation_peak_frontier_scores":navigation.peak_frontier_scores,"navigation_distance_evaluations":navigation.distance_evaluations,"cache_entries":c.records.len(),"peak_cache_entries":c.peak_entries,"cache_entry_cap":self.limits.entries,"cache_payload_bytes":c.bytes,"peak_cache_payload_bytes":c.peak,"cache_payload_cap_bytes":self.limits.cache_payload_bytes,"evictions":c.evictions,"hits":c.hits,"misses":c.misses,"durable_point_reads":self.reads.load(Ordering::Relaxed),"durable_root_commits":self.writes.load(Ordering::Relaxed),"authored_record_encoded_bytes":self.encoded_set_bytes.load(Ordering::Relaxed),"logical_record_return_bytes":self.returned_bytes.load(Ordering::Relaxed),"mutation_working_active_bytes":self.working.load(Ordering::Relaxed),"mutation_working_peak_reserved_bytes":self.working_peak.load(Ordering::Relaxed),"mutation_working_cap_bytes":self.limits.mutation_working_bytes,"completed_structural_scopes":self.epoch.load(Ordering::Relaxed),"poisoned":self.failed.load(Ordering::Relaxed),"scope":"Capped clean-record payload and modeled mutation reservation only. Provider/root/encoded/decode/container allocations and caller-owned frontier vectors are separate. One durable fork/commit per changed owner per outer structural scope is charged. Dirty record staging and cloned flush input are admitted separately from the clean cache. Parent-plus-child wave pin payload is a conservative accounted upper bound, not exact live allocation. Frontier score vectors are separate. Coordinator mutation graph and owner placement remain resident metadata."})}
}
fn encode(record:&NodeRecord)->Result<Vec<u32>>{let(epoch,owner)=match record.binding{Binding::Live{owner,epoch}=>(epoch,owner),_=>unreachable!()};let (tag,count,children)=match &record.kind{Kind::Leaf{physical_rows}=>(0,*physical_rows,vec![]),Kind::Internal{children}=>(1,children.len(),children.clone())};let count=u32::try_from(count).map_err(|_|anyhow::anyhow!("live node row/child count overflow"))?;let mut words=vec![0x544f5031,owner as u32,epoch as u32,(epoch>>32) as u32,record.parent.unwrap_or(u32::MAX),tag,record.centroid.len() as u32,count];words.extend(record.centroid.iter().map(|v|v.to_bits()));words.extend(children);Ok(words)}
fn decode(id:u32,owner:usize,words:&[u32],dim:usize,cap:usize)->Result<NodeRecord>{ensure!(words.len()>=8 && words[0]==0x544f5031 && words[1] as usize==owner && words[6] as usize==dim,"live record header");let count=words[7] as usize;let children=if words[5]==1{count}else{ensure!(words[5]==0,"live kind");0};ensure!(words.len()==8+dim+children && dim.checked_mul(4).and_then(|v|v.checked_add(children*4)).is_some_and(|v|v<=cap),"live record extent/admission");let centroid:Vec<_>=words[8..8+dim].iter().map(|v|f32::from_bits(*v)).collect();ensure!(centroid.iter().all(|v|v.is_finite()),"live centroid finite");Ok(NodeRecord{id,parent:(words[4]!=u32::MAX).then_some(words[4]),centroid,kind:if words[5]==0{Kind::Leaf{physical_rows:count}}else{Kind::Internal{children:words[8+dim..].to_vec()}},binding:Binding::Live{owner,epoch:u64::from(words[2])|(u64::from(words[3])<<32)}})}

#[cfg(test)]mod tests{
 use super::*;
 #[test]fn live_topology_shared_readers_exclusive_writer_and_nested_reservation_progress(){
  use chroma_blockstore::arrow::provider::ArrowBlockfileProvider;use chroma_cache::new_cache_for_test;use chroma_storage::{local::LocalStorage,Storage};use std::sync::{Barrier,mpsc};use std::time::Duration;
  let dir=tempfile::tempdir().unwrap();let provider=BlockfileProvider::ArrowBlockfileProvider(ArrowBlockfileProvider::new(Storage::Local(LocalStorage::new(dir.path().to_str().unwrap())),16*1024,new_cache_for_test(),new_cache_for_test(),2));
  let store=Arc::new(LiveTopology::new(provider,2,32,Limits{entries:2,cache_payload_bytes:512,record_payload_bytes:512,wave_rows:2,mutation_working_bytes:1024*1024}).unwrap());
  let release=Arc::new(Barrier::new(3));let(ready_tx,ready_rx)=mpsc::channel();let mut readers=Vec::new();
  for _ in 0..2{let store=store.clone();let release=release.clone();let ready=ready_tx.clone();readers.push(std::thread::spawn(move||{let _read=store.read_scope().unwrap();ready.send(()).unwrap();release.wait();}));}
  ready_rx.recv_timeout(Duration::from_secs(2)).unwrap();ready_rx.recv_timeout(Duration::from_secs(2)).unwrap();
  let(attempt_tx,attempt_rx)=mpsc::channel();let(done_tx,done_rx)=mpsc::channel();let writing=store.clone();let writer=std::thread::spawn(move||{attempt_tx.send(()).unwrap();let outer=writing.reserve_mutation(2).unwrap();{let _write=writing.write_scope();let _same_thread_read=writing.read_scope().unwrap();let nested=writing.reserve_mutation(3).unwrap();let active=writing.working.load(Ordering::Relaxed);{let _recursive=writing.write_scope();drop(nested);}assert_eq!(writing.working.load(Ordering::Relaxed),active,"recursive dirty reservation survives until outer flush");assert!(writing.deferred_working.load(Ordering::Relaxed)>0);writing.flush().unwrap();assert_eq!(writing.working.load(Ordering::Relaxed),outer.bytes);}drop(outer);done_tx.send(()).unwrap();});
  attempt_rx.recv_timeout(Duration::from_secs(2)).unwrap();assert!(done_rx.recv_timeout(Duration::from_millis(20)).is_err(),"writer waits for both active read views");release.wait();for reader in readers{reader.join().unwrap();}done_rx.recv_timeout(Duration::from_secs(2)).unwrap();writer.join().unwrap();assert_eq!(store.working.load(Ordering::Relaxed),0);assert_eq!(store.report()["poisoned"],false);
 }
}
